INSERT INTO profiles(gender,name,age,state,city,about,marital_status,annual_income,description,caste,religion,whatsapp) SELECT 'female',CONCAT('Profile ',n),23+(n%7),'Uttar Pradesh',CASE WHEN n%4=0 THEN 'Lucknow' WHEN n%4=1 THEN 'Kanpur' WHEN n%4=2 THEN 'Agra' ELSE 'Varanasi' END,'Sample profile for demonstration.','Never Married','₹4-8 Lakh','Sample profile data.','General','Hindu',CONCAT('90000000',LPAD(10+n,2,'0')) FROM (SELECT 11 n UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30) t;
